configuration.decoder:
/** Decoder **/

// Decodifica il payload arrivato come array di byte o stringa
var data = {};

try {
    data = decodeToJson(payload);
} catch (e) {
    data = {};
}

// Nel caso il messaggio sia incapsulato da ThingsBoard/Sentinel
var p = {};
if (data && data.payload) {
    p = data.payload;
} else if (data) {
    p = data;
}

// Estrazione sicura delle sezioni annidate
var hw = p.hw || {};
var ram = hw.ram || {};
var disk = hw.disk || {};

var analysis = p.analysis || {};
var stage = analysis.stage || {};
var population = analysis.population || {};
var network = analysis.network || {};
var kinetics = analysis.kinetics || {};
var hypha = analysis.hypha_growth || {};

// Sotto-oggetti statistici di population
var popDiam = population.diameter_um || {};
var popArea = population.area_um2 || {};
var popSkel = population.germinated_skeleton_length_um || {};
var popCirc = population.circularity || {};

// Funzioni helper per la pulizia dei dati
function safeNumber(value, fallback) {
    if (value === undefined || value === null || value === "") {
        return fallback;
    }
    var n = Number(value);
    return isNaN(n) ? fallback : n;
}

function safeString(value, fallback) {
    if (value === undefined || value === null) {
        return fallback;
    }
    return String(value);
}

function boolToNumber(value) {
    return value === true ? 1 : 0;
}

/** Functions di supporto di ThingsBoard **/

function decodeToString(payload) {
    return String.fromCharCode.apply(String, payload);
}

function decodeToJson(payload) {
    var str = decodeToString(payload);
    return JSON.parse(str);
}

// Oggetto finale di output registrato su ThingsBoard
return {
    deviceName: safeString(p.device_id, "sensore_001"),
    deviceType: "Optical Biosensor",

    attributes: {
        sample_id: safeString(p.sample_id, ""),
        image_name: safeString(p.image_name, ""),
        image_path: safeString(analysis.image_path, ""),
        um_per_pixel: safeNumber(p.um_per_pixel, 0),
        status: safeString(analysis.status, ""),
        integrationName: metadata ? metadata['integrationName'] : ""
    },

    telemetry: {
        frame_id: safeNumber(p.frame_id, 0),
        timestamp: safeString(p.timestamp, ""),

        // Analisi dello Stadio di Crescita
        detected: boolToNumber(analysis.detected),
        growth_stage: safeString(stage.growth_stage, ""),
        growth_stage_raw: safeString(stage.growth_stage_raw, ""),
        risk_level: safeString(stage.risk_level, ""),
        stage_confirmed: boolToNumber(stage.stage_confirmed),
        development_index: safeNumber(stage.development_index, 0),

        // Popolazione e Germinazione
        spore_count: safeNumber(population.object_count, 0), // mappato su object_count
        germinated_count: safeNumber(population.germinated_count, 0),
        germination_percent: safeNumber(population.germination_percent, 0),
        
        // Statistiche Dimensione e Forma
        diameter_mean_um: safeNumber(popDiam.mean, 0),
        diameter_median_um: safeNumber(popDiam.median, 0),
        area_mean_um2: safeNumber(popArea.mean, 0),
        circularity_mean: safeNumber(popCirc.mean, 0),
        germinated_skeleton_length_mean_um: safeNumber(popSkel.mean, 0),

        // Rete Miceliale (Network)
        biological_area_um2: safeNumber(network.biological_area_um2, 0),
        biological_area_percent: safeNumber(network.biological_area_percent, 0),
        network_area_percent: safeNumber(network.network_area_percent, 0),
        skeleton_length_um: safeNumber(network.skeleton_length_um, 0),
        network_components_count: safeNumber(network.network_components_count, 0),
        branch_points_count: safeNumber(network.branch_points_count, 0),
        endpoints_count: safeNumber(network.endpoints_count, 0),
        branching_density_per_mm: safeNumber(network.branching_density_per_mm, 0),

        // Crescita Ite e Cinetica (Kinetics & Hypha)
        new_growth_um: safeNumber(hypha.new_growth_um, 0),
        tracks_with_hypha: safeNumber(hypha.tracks_with_hypha, 0),
        tracked_spore_count: safeNumber(kinetics.tracked_spore_count, 0),
        germinated_track_count: safeNumber(kinetics.germinated_track_count, 0),
        cumulative_germination_percent: safeNumber(kinetics.cumulative_germination_percent, 0),
        avg_time_to_germination_s: safeNumber(kinetics.avg_time_to_germination_s, 0),
        avg_elongation_rate_um_per_min: safeNumber(kinetics.avg_elongation_rate_um_per_min, 0),

        // Hardware Telemetry
        cpu_temp_c: safeNumber(hw.cpu_temp_c, 0),
        processing_time_s: safeNumber(hw.processing_time_s, 0),

        ram_used_mb: safeNumber(ram.used_mb, 0),
        ram_total_mb: safeNumber(ram.total_mb, 0),
        ram_used_percent: safeNumber(ram.used_percent, 0),

        disk_used_mb: safeNumber(disk.used_mb, 0),
        disk_free_mb: safeNumber(disk.free_mb, 0),
        disk_used_percent: safeNumber(disk.used_percent, 0)
    }
};

configuration.tbelDecoder:
/** Decoder **/

var data = decodeToJson(payload);

// Nel debug di ThingsBoard/Sentinel il messaggio arriva spesso come:
// {
//   "topic": "...",
//   "payload": {...}
// }
//
// Nel messaggio MQTT reale invece potrebbe arrivare direttamente:
// {
//   "device_id": "...",
//   ...
// }

var p = {};

if (data && data.payload) {
    p = data.payload;
} else if (data) {
    p = data;
}

var hw = p.hw || {};
var ram = hw.ram || {};
var disk = hw.disk || {};
var analysis = p.analysis || {};

function safeNumber(value, fallback) {
    if (value === undefined || value === null || value === "") {
        return fallback;
    }

    var n = Number(value);

    if (isNaN(n)) {
        return fallback;
    }

    return n;
}

function safeString(value, fallback) {
    if (value === undefined || value === null) {
        return fallback;
    }

    return String(value);
}

function boolToNumber(value) {
    return value === true ? 1 : 0;
}

return {
    deviceName: safeString(p.device_id, "sensore_001"),
    deviceType: "Optical Biosensor",

    attributes: {
        sample_id: safeString(p.sample_id, ""),
        image_name: safeString(p.image_name, ""),
        image_path: safeString(analysis.image_path, "")
    },

    telemetry: {
        frame_id: safeNumber(p.frame_id, 0),

        detected: boolToNumber(analysis.detected),
        spore_count: safeNumber(analysis.spore_count, 0),

        growth_stage: safeString(analysis.growth_stage, ""),
        growth_stage_raw: safeString(analysis.growth_stage_raw, ""),
        risk_level: safeString(analysis.risk_level, ""),
        stage_confirmed: boolToNumber(analysis.stage_confirmed),

        development_index: safeNumber(analysis.development_index, 0),
        tracked_spore_count: safeNumber(analysis.tracked_spore_count, 0),
        cumulative_germination_percent: safeNumber(analysis.cumulative_germination_percent, 0),
        avg_time_to_germination_s: safeNumber(analysis.avg_time_to_germination_s, 0),
        avg_elongation_rate_um_per_min: safeNumber(analysis.avg_elongation_rate_um_per_min, 0),

        cpu_temp_c: safeNumber(hw.cpu_temp_c, 0),
        processing_time_s: safeNumber(hw.processing_time_s, 0),

        ram_used_mb: safeNumber(ram.used_mb, 0),
        ram_total_mb: safeNumber(ram.total_mb, 0),
        ram_used_percent: safeNumber(ram.used_percent, 0),

        disk_used_mb: safeNumber(disk.used_mb, 0),
        disk_free_mb: safeNumber(disk.free_mb, 0),
        disk_used_percent: safeNumber(disk.used_percent, 0)
    }
};
